package postgres

import (
	"context"
	"strings"
	"testing"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/mudler/localrecall/rag/raw"
)

// Query tracing supplies a deterministic arm boundary without production hooks.
type armBarrier struct {
	entered chan struct{}
	release chan struct{}
}

func (b *armBarrier) TraceQueryStart(ctx context.Context, _ *pgx.Conn, d pgx.TraceQueryStartData) context.Context {
	if strings.HasPrefix(d.SQL, "SELECT id,text,metadata,-(") {
		close(b.entered)
		select {
		case <-b.release:
		case <-ctx.Done():
		}
	}
	return ctx
}
func (*armBarrier) TraceQueryEnd(context.Context, *pgx.Conn, pgx.TraceQueryEndData) {}
func TestRawSearchSnapshotAndCancellation(t *testing.T) {
	for _, cancelArm := range []bool{false, true} {
		t.Run(map[bool]string{false: "snapshot", true: "cancel_after_vector"}[cancelArm], func(t *testing.T) {
			s, ctx, id := recordFixture(t)
			text := "bicycle"
			put(t, s, ctx, id, raw.Record{ID: "a", Vector: []float64{1, 0, 0}, Text: &text})
			writer, e := New(ctx, Config{s.pool.Config().ConnString()})
			if e != nil {
				t.Fatal(e)
			}
			defer writer.Close()
			barrier := &armBarrier{make(chan struct{}), make(chan struct{})}
			cfg := s.pool.Config()
			cfg.ConnConfig.Tracer = barrier
			s.pool.Close()
			s.pool, e = pgxpool.NewWithConfig(ctx, cfg)
			if e != nil {
				t.Fatal(e)
			}
			requestCtx, cancel := context.WithTimeout(ctx, 10*time.Second)
			defer cancel()
			type answer struct {
				out raw.SearchResponse
				err error
			}
			done := make(chan answer, 1)
			go func() { out, e := s.Search(requestCtx, id, searchRequest("hybrid")); done <- answer{out, e} }()
			select {
			case <-barrier.entered:
			case <-requestCtx.Done():
				t.Fatal("lexical arm not reached")
			}
			if cancelArm {
				cancel()
			} else {
				other := "ocean"
				put(t, writer, ctx, id, raw.Record{ID: "a", Vector: []float64{0, 1, 0}, Text: &other})
			}
			close(barrier.release)
			got := <-done
			if cancelArm {
				checkCode(t, got.err, raw.CodeTimeout)
				if got.out.Results != nil || got.out.Count != 0 {
					t.Fatal("partial response", got)
				}
				return
			}
			if got.err != nil || got.out.Count != 1 {
				t.Fatal(got)
			}
			hit := got.out.Results[0]
			if hit.Text == nil || *hit.Text != "bicycle" || hit.LexicalRank == nil || hit.VectorRank == nil || hit.Score != 1.0/61 {
				t.Fatalf("mixed snapshot: %+v", hit)
			}
		})
	}
}

package postgres

import (
	"context"
	"fmt"
	"github.com/mudler/localrecall/rag/raw"
	"math"
	"testing"
)

func searchRequest(mode string) raw.SearchRequest {
	space, text, exact := "space", "bicycle", "exact"
	r := raw.SearchRequest{Mode: mode}
	if mode != "lexical" {
		r.Vector = []float64{1, 0, 0}
		r.EmbeddingSpaceID = &space
		r.Accuracy = &exact
	}
	if mode != "vector" {
		r.Text = &text
	}
	return r
}
func TestRawSearchModes(t *testing.T) {
	s, ctx, id := recordFixture(t)
	text := "bicycle bicycle"
	other := "ocean"
	put(t, s, ctx, id, raw.Record{ID: "b", Vector: []float64{1, 0, 0}, Text: &text, Metadata: map[string]string{"keep": "yes"}}, raw.Record{ID: "a", Vector: []float64{1, 0, 0}, Text: &text, Metadata: map[string]string{"keep": "yes"}}, raw.Record{ID: "z", Vector: []float64{0, 1, 0}, Text: &other})
	for _, mode := range []string{"vector", "lexical", "hybrid"} {
		r := searchRequest(mode)
		r.Filter = &raw.Filter{MetadataEq: map[string]string{"keep": "yes"}}
		got, e := s.Search(ctx, id, r)
		if e != nil || got.Count != 2 || got.Results[0].ID != "a" {
			t.Fatalf("%s: %+v %v", mode, got, e)
		}
		if got.Mode != mode || got.Count != len(got.Results) {
			t.Fatal(got)
		}
		wantAccuracy, wantKind := "exact", "cosine_similarity"
		if mode == "lexical" {
			wantAccuracy, wantKind = "not_applicable", "bm25"
		}
		if mode == "hybrid" {
			wantKind = "rrf"
		}
		if got.Accuracy != wantAccuracy || got.ScoreKind != wantKind {
			t.Fatal(got)
		}
		if mode == "hybrid" {
			if got.Fusion == nil || got.Fusion.K != 60 || got.Fusion.VectorWeight != 0.5 || got.Fusion.LexicalWeight != 0.5 {
				t.Fatal(got)
			}
			if got.Results[0].VectorRank == nil || *got.Results[0].VectorRank != 1 || got.Results[0].LexicalRank == nil || *got.Results[0].LexicalRank != 1 {
				t.Fatal(got)
			}
			if got.Fusion.CandidatesPerArm != 100 || math.Abs(got.Results[0].Score-1.0/61) > 1e-12 {
				t.Fatal(got)
			}
		}
		if mode == "lexical" && got.Results[0].Score <= 0 {
			t.Fatal("BM25 must be higher-is-better", got)
		}
	}
	r := searchRequest("lexical")
	empty := "nomatchingterm"
	r.Text = &empty
	got, e := s.Search(ctx, id, r)
	if e != nil || got.Count != 0 {
		t.Fatal(got, e)
	}
	r = searchRequest("vector")
	wrong := "wrong"
	r.EmbeddingSpaceID = &wrong
	_, e = s.Search(ctx, id, r)
	checkCode(t, e, raw.CodeSpaceMismatch)
	r = searchRequest("vector")
	r.Vector = []float64{1, 0}
	_, e = s.Search(ctx, id, r)
	checkCode(t, e, raw.CodeValidation)
	canceled, cancel := context.WithCancel(ctx)
	cancel()
	got, e = s.Search(canceled, id, searchRequest("hybrid"))
	checkCode(t, e, raw.CodeTimeout)
	if got.Results != nil {
		t.Fatal("partial response")
	}
}
func TestRawSearchMissingIndexes(t *testing.T) {
	s, ctx, id := recordFixture(t)
	put(t, s, ctx, id, rec("a"))
	exec(t, s, `DROP INDEX "lr_ann_`+id+`"`)
	r := searchRequest("vector")
	r.Accuracy = nil
	_, e := s.Search(ctx, id, r)
	checkCode(t, e, raw.CodeUnavailable)
	if _, e = s.Search(ctx, id, searchRequest("vector")); e != nil {
		t.Fatal(e)
	}
	exec(t, s, `DROP INDEX "lr_bm25_`+id+`"`)
	_, e = s.Search(ctx, id, searchRequest("lexical"))
	checkCode(t, e, raw.CodeUnavailable)
}

// An ANN access method alone is insufficient: L2 cannot order a cosine query.
func TestRawSearchANNOperatorClass(t *testing.T) {
	s, ctx, id := recordFixture(t)
	text := "bicycle"
	put(t, s, ctx, id, raw.Record{ID: "a", Vector: []float64{1, 0, 0}, Text: &text})
	table, _ := tableName(id)
	for _, opclass := range []string{"vector_l2_ops", "vector_cosine_ops"} {
		exec(t, s, `DROP INDEX "lr_ann_`+id+`"`)
		exec(t, s, `CREATE INDEX "lr_ann_`+id+`" ON `+table+` USING hnsw (vector `+opclass+`)`)
		for _, mode := range []string{"vector", "hybrid"} {
			for _, accuracy := range []string{"approximate", "exact"} {
				t.Run(opclass+"/"+mode+"/"+accuracy, func(t *testing.T) {
					r := searchRequest(mode)
					r.Accuracy = &accuracy
					got, e := s.Search(ctx, id, r)
					if opclass == "vector_l2_ops" && accuracy == "approximate" {
						checkCode(t, e, raw.CodeUnavailable) // HTTP 503, not silent exact fallback.
						if got.Results != nil {
							t.Fatal("partial response", got)
						}
						return
					}
					if e != nil || got.Count != 1 || got.Results[0].ID != "a" || got.Accuracy != accuracy {
						t.Fatalf("response=%+v error=%v", got, e)
					}
				})
			}
		}
	}
}

// Regression: pg_textsearch takes an index *name*, not SQL-quoted regclass
// syntax. UUID hyphens make this distinction observable on every collection.
func TestRawSearchBM25LiteralIndex(t *testing.T) {
	s, ctx, id := recordFixture(t)
	text := "bicycle"
	put(t, s, ctx, id, raw.Record{ID: "a", Vector: []float64{1, 0, 0}, Text: &text})
	table, _ := tableName(id)
	var distance float64
	if e := s.pool.QueryRow(ctx, `SELECT text <@> to_bm25query($1,$2) FROM `+table, text, "lr_bm25_"+id).Scan(&distance); e != nil {
		t.Fatal(e)
	}
	got, e := s.Search(ctx, id, searchRequest("lexical"))
	if e != nil || got.Count != 1 || got.Results[0].Score != -distance || distance >= 0 {
		t.Fatalf("literal index distance=%g response=%+v error=%v", distance, got, e)
	}
}
func TestRawSearchCandidateBounds(t *testing.T) {
	for _, c := range []struct{ k, n int }{{1, 100}, {10, 100}, {11, 110}, {100, 1000}} {
		if candidateN(c.k) != c.n {
			t.Fatal(c)
		}
	}
	s, ctx, id := recordFixture(t)
	// Globally higher-ranked excluded rows exceed either candidate limit.
	for batch := 0; batch < 3; batch++ {
		rs := []raw.Record{}
		for i := 0; i < 100; i++ {
			text := "bicycle"
			rs = append(rs, raw.Record{ID: fmt.Sprintf("a%03d", batch*100+i), Vector: []float64{1, 0, 0}, Text: &text})
		}
		put(t, s, ctx, id, rs...)
	}
	text := "bicycle"
	put(t, s, ctx, id, raw.Record{ID: "z", Vector: []float64{0, 1, 0}, Text: &text, Metadata: map[string]string{"keep": "yes"}})
	for _, mode := range []string{"vector", "lexical", "hybrid"} {
		r := searchRequest(mode)
		k := 1
		r.TopK = &k
		r.Filter = &raw.Filter{MetadataEq: map[string]string{"keep": "yes"}}
		got, e := s.Search(ctx, id, r)
		if e != nil || got.Count != 1 || got.Results[0].ID != "z" {
			t.Fatal(mode, got, e)
		}
		if mode == "hybrid" && (got.Results[0].VectorRank == nil || got.Results[0].LexicalRank == nil || got.Results[0].Score != 1.0/61) {
			t.Fatal(got)
		}
	}
	// Without a filter, z lies outside BOTH bounded arms, even exact hybrid.
	r := searchRequest("hybrid")
	k := 10
	r.TopK = &k
	got, e := s.Search(ctx, id, r)
	if e != nil {
		t.Fatal(e)
	}
	for _, h := range got.Results {
		if h.ID == "z" {
			t.Fatal("unexpected boundary result")
		}
	}
}
func TestRawSearchDisabledLexical(t *testing.T) {
	s, ctx := fixture(t)
	r := request()
	disabled := false
	r.Lexical = &raw.LexicalRequest{Enabled: &disabled}
	c, _, e := s.CreateCollection(ctx, r)
	if e != nil {
		t.Fatal(e)
	}
	defer s.DeleteCollection(ctx, c.CollectionID)
	for _, mode := range []string{"lexical", "hybrid"} {
		got, e := s.Search(ctx, c.CollectionID, searchRequest(mode))
		// Immutable configuration does not implement this collection capability (501).
		// Unlike a configured capability with a missing runtime index (503),
		// retrying cannot restore it. Preserve the Task1 validator contract.
		checkCode(t, e, raw.CodeUnsupported)
		if got.Results != nil {
			t.Fatal(got)
		}
	}
	if _, e = s.Search(ctx, c.CollectionID, searchRequest("vector")); e != nil {
		t.Fatal(e)
	}
}

// A lexical-only hit beyond the bounded vector arm must not acquire a global
// vector rank. Approximate candidates may differ, but remain bounded and tied
// by ID within each returned arm; no exact membership is promised for ANN.
func TestRawSearchCandidateUnion(t *testing.T) {
	s, ctx, id := recordFixture(t)
	for batch := 0; batch < 2; batch++ {
		records := []raw.Record{}
		for i := batch * 100; i < min(110, (batch+1)*100); i++ {
			text := "ocean"
			if i >= 99 {
				text = "bicycle"
			}
			records = append(records, raw.Record{ID: fmt.Sprintf("a%03d", i), Vector: []float64{1, 0, 0}, Text: &text})
		}
		put(t, s, ctx, id, records...)
	}
	for _, accuracy := range []string{"exact", "approximate"} {
		r := searchRequest("hybrid")
		r.Accuracy = &accuracy
		got, e := s.Search(ctx, id, r)
		if e != nil || got.Count != 10 || got.Fusion.CandidatesPerArm != 100 {
			t.Fatal(got, e)
		}
		foundBoundary := false
		for i, h := range got.Results {
			score := 0.0
			if h.VectorRank != nil {
				if *h.VectorRank < 1 || *h.VectorRank > 100 {
					t.Fatal(h)
				}
				score += 0.5 / float64(60+*h.VectorRank)
			}
			if h.LexicalRank != nil {
				score += 0.5 / float64(60+*h.LexicalRank)
			}
			if math.Abs(score-h.Score) > 1e-12 {
				t.Fatal(h)
			}
			if i > 0 && (got.Results[i-1].Score < h.Score || (got.Results[i-1].Score == h.Score && got.Results[i-1].ID > h.ID)) {
				t.Fatal("unstable fusion order", got)
			}
			if accuracy == "exact" && h.ID == "a100" {
				foundBoundary = true
				if h.VectorRank != nil || h.LexicalRank == nil || *h.LexicalRank != 2 {
					t.Fatal("candidate boundary ignored", h)
				}
			}
		}
		if accuracy == "exact" && (!foundBoundary || got.Results[0].ID != "a099") {
			t.Fatal("expected bounded union", got)
		}
	}
}

package e2e_test

import (
	"context"
	"fmt"
	"os"

	"github.com/mudler/localrecall/pkg/client"
	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
	"github.com/sashabaranov/go-openai"
)

var _ = Describe("Hybrid Search E2E", func() {
	var (
		localAI     *openai.Client
		localRecall *client.Client
	)

	BeforeEach(func() {
		if os.Getenv("E2E") != "true" {
			Skip("Skipping E2E tests")
		}

		localAI = openai.NewClientWithConfig(NewTestOpenAIConfig())
		localRecall = client.NewClient(localRecallEndpoint)

		Eventually(func() error {
			res, err := localAI.CreateEmbeddings(context.Background(), openai.EmbeddingRequest{
				Model: EmbeddingModel,
				Input: "foo",
			})
			if len(res.Data) == 0 {
				return fmt.Errorf("no data")
			}
			return err
		}, TestTimeout, TestPollingInterval).Should(Succeed())

		Eventually(func() error {
			_, err := localRecall.ListCollections()
			return err
		}, TestTimeout, TestPollingInterval).Should(Succeed())

		localRecall.Reset(TestCollection)
	})

	It("should perform hybrid search combining BM25 and vector search", func() {
		err := localRecall.CreateCollection(TestCollection)
		Expect(err).ToNot(HaveOccurred())

		// Store documents with specific keywords
		tempContent("Database connection pooling is important for performance", localRecall)
		tempContent("PostgreSQL authentication methods include password and certificate", localRecall)
		tempContent("Vector search uses embeddings for semantic similarity", localRecall)

		// Search should find relevant documents using both keyword and semantic search
		docs, err := localRecall.Search(TestCollection, "database connection", 3)
		Expect(err).To(BeNil())
		Expect(len(docs)).To(BeNumerically(">=", 1))
		Expect(docs[0].Content).To(ContainSubstring("connection"))
	})
})

package postgres

import (
	"context"
	"sort"

	"github.com/jackc/pgx/v5"
	"github.com/mudler/localrecall/rag/internal/pgutil"
	"github.com/mudler/localrecall/rag/raw"
)

var _ raw.Store = (*Service)(nil)

func candidateN(k int) int { return min(1000, max(100, 10*k)) }

// vectorQuery fences exact ranking behind materialization: no ANN access path
// can implement an ORDER BY on this CTE. Approximate keeps the bare operator.
// SQL predicates precede LIMIT, but ANN traversal can still underfill or lose
// filtered recall. Never expand candidates without bounds or retry as exact.
func vectorQuery(table, predicate string, exact bool) string {
	if exact {
		return `WITH eligible AS MATERIALIZED (SELECT id,text,metadata,vector FROM ` + table + ` WHERE ` + predicate + `) SELECT id,text,metadata,1-(vector <=> $1::vector) FROM eligible ORDER BY vector <=> $1::vector,id COLLATE "C" LIMIT $2`
	}
	return `SELECT id,text,metadata,1-(vector <=> $1::vector) FROM ` + table + ` WHERE ` + predicate + ` ORDER BY vector <=> $1::vector,id COLLATE "C" LIMIT $2`
}
func lexicalQuery(table, index, predicate string) string {
	distance := pgutil.BM25Distance("text", "$1", index)
	return `SELECT id,text,metadata,-(` + distance + `) FROM ` + table + ` WHERE ` + predicate + ` AND (` + distance + `) < 0 ORDER BY ` + distance + `,id COLLATE "C" LIMIT $2`
}
func searchRows(ctx context.Context, tx pgx.Tx, q string, args []any) ([]raw.SearchResult, error) {
	rows, e := tx.Query(ctx, q, args...)
	if e != nil {
		return nil, e
	}
	defer rows.Close()
	out := []raw.SearchResult{}
	for rows.Next() {
		var r raw.SearchResult
		if e = rows.Scan(&r.ID, &r.Text, &r.Metadata, &r.Score); e != nil {
			return nil, e
		}
		out = append(out, r)
	}
	return out, rows.Err()
}

// Search never accepts an embedder: opaque caller vectors identify their space.
// Both arms and their payloads use one repeatable-read snapshot. Errors, including
// cancellation/commit failures, discard all results; BM25 never falls back.
func (s *Service) Search(ctx context.Context, id string, r raw.SearchRequest) (out raw.SearchResponse, err error) {
	err = s.transaction(ctx, pgx.RepeatableRead, func(ctx context.Context, tx pgx.Tx) error {
		c, e := lookup(ctx, tx, id)
		if e != nil {
			return e
		}
		r, e = raw.ValidateSearch(c, r)
		if e != nil {
			return e
		}
		table, _ := tableName(id)
		k := *r.TopK
		n := k
		if r.Mode == "hybrid" {
			n = candidateN(k)
		}
		out = raw.SearchResponse{Mode: r.Mode, Accuracy: "not_applicable", ScoreKind: "bm25", Results: []raw.SearchResult{}}
		var vs, ls []raw.SearchResult
		if r.Mode != "lexical" {
			out.Accuracy = *r.Accuracy
			out.ScoreKind = "cosine_similarity"
			if *r.Accuracy == "approximate" {
				strategy, e := pgutil.IndexStrategy(ctx, tx, table, "lr_ann_"+id, "vector")
				if e != nil {
					return e
				}
				if strategy != "hnsw" && strategy != "diskann" {
					return raw.NewError(raw.CodeUnavailable)
				}
			}
			v := make([]float32, len(r.Vector))
			for i, x := range r.Vector {
				v[i] = float32(x)
			}
			args := []any{pgutil.Vector(v), n}
			predicate := metadataPredicate(r.Filter, &args)
			vs, e = searchRows(ctx, tx, vectorQuery(table, predicate, *r.Accuracy == "exact"), args)
			if e != nil {
				return e
			}
			for i := range vs {
				rank, sim := i+1, vs[i].Score
				vs[i].VectorRank = &rank
				vs[i].VectorSimilarity = &sim
			}
		}
		if r.Mode != "vector" {
			strategy, e := pgutil.IndexStrategy(ctx, tx, table, "lr_bm25_"+id, "text")
			if e != nil {
				return e
			}
			if strategy != "bm25" {
				return raw.NewError(raw.CodeUnavailable)
			}
			args := []any{*r.Text, n}
			predicate := metadataPredicate(r.Filter, &args)
			// pg_textsearch resolves the literal index name, not a regclass literal.
			ls, e = searchRows(ctx, tx, lexicalQuery(table, "lr_bm25_"+id, predicate), args)
			if e != nil {
				return e
			}
			for i := range ls {
				rank := i + 1
				ls[i].LexicalRank = &rank
			}
		}
		switch r.Mode {
		case "vector":
			out.Results = vs
		case "lexical":
			out.Results = ls
		case "hybrid":
			out.ScoreKind = "rrf"
			out.Fusion = &raw.FusionParameters{K: 60, VectorWeight: 0.5, LexicalWeight: 0.5, CandidatesPerArm: n}
			merged := map[string]raw.SearchResult{}
			for _, v := range vs {
				v.Score = 0.5 / float64(60+*v.VectorRank)
				merged[v.ID] = v
			}
			for _, l := range ls {
				v, ok := merged[l.ID]
				if !ok {
					v = l
					v.Score = 0
				}
				v.LexicalRank = l.LexicalRank
				v.Score += 0.5 / float64(60+*l.LexicalRank)
				merged[l.ID] = v
			}
			for _, v := range merged {
				out.Results = append(out.Results, v)
			}
			sort.Slice(out.Results, func(i, j int) bool {
				a, b := out.Results[i], out.Results[j]
				if a.Score == b.Score {
					return a.ID < b.ID
				}
				return a.Score > b.Score
			})
			if len(out.Results) > k {
				out.Results = out.Results[:k]
			}
		}
		out.Count = len(out.Results)
		return ctx.Err()
	})
	if err != nil {
		out = raw.SearchResponse{}
	}
	return
}

package rag_test

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	. "github.com/mudler/localrecall/rag"
	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
	"github.com/sashabaranov/go-openai"
)

var _ = Describe("NewPersistentPostgresCollection", func() {
	var databaseURL string

	BeforeEach(func() {
		databaseURL = os.Getenv("LOCALRECALL_TEST_DATABASE_URL")
		if databaseURL == "" {
			databaseURL = "postgresql://localrecall:localrecall@localhost:5432/localrecall?sslmode=disable"
		}
		ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
		defer cancel()
		p, err := pgxpool.New(ctx, databaseURL)
		if err != nil {
			Skip(fmt.Sprintf("postgres unavailable: %v", err))
		}
		defer p.Close()
		if err := p.Ping(ctx); err != nil {
			Skip(fmt.Sprintf("postgres unreachable: %v", err))
		}
	})

	// When the knowledge base cannot be built around a working PostgreSQL
	// engine, the engine is discarded. Its connections must be closed too.
	It("keeps no server connection open when the knowledge base cannot be created", func() {
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			_ = json.NewEncoder(w).Encode(map[string]any{
				"object": "list",
				"model":  "fake",
				"data": []map[string]any{{
					"object": "embedding", "index": 0, "embedding": []float32{0.1, 0.2, 0.3, 0.4},
				}},
			})
		}))
		defer srv.Close()
		cfg := openai.DefaultConfig("sk-test")
		cfg.BaseURL = srv.URL + "/v1"
		client := openai.NewClientWithConfig(cfg)

		tmp, err := os.MkdirTemp("", "collection_pg_leak_*")
		Expect(err).NotTo(HaveOccurred())
		defer func() { _ = os.RemoveAll(tmp) }()
		// A regular file where the asset directory should go makes the
		// knowledge base creation fail after the engine is open.
		blocker := filepath.Join(tmp, "assets")
		Expect(os.WriteFile(blocker, nil, 0o600)).To(Succeed())

		appName := fmt.Sprintf("localrecall_leak_test_%d", time.Now().UnixNano())
		sep := "?"
		if strings.Contains(databaseURL, "?") {
			sep = "&"
		}
		url := databaseURL + sep + "application_name=" + appName
		name := fmt.Sprintf("leak_test_%d", time.Now().UnixNano())

		kb, err := NewPersistentPostgresCollection(client, name, tmp, blocker, "fake", 1000, 0, url)
		if err != nil && strings.Contains(err.Error(), "create PostgresDB") {
			Skip(fmt.Sprintf("the PostgreSQL engine cannot start on this database: %v", err))
		}
		Expect(err).To(MatchError(ContainSubstring("create PersistentKB")))
		Expect(kb).To(BeNil())

		admin, err := pgxpool.New(context.Background(), databaseURL)
		Expect(err).NotTo(HaveOccurred())
		defer admin.Close()
		defer func() {
			_, _ = admin.Exec(context.Background(), "DROP TABLE IF EXISTS documents_"+name+" CASCADE")
		}()
		Eventually(func() int {
			var n int
			Expect(admin.QueryRow(context.Background(),
				"SELECT count(*) FROM pg_stat_activity WHERE application_name = $1", appName).Scan(&n)).To(Succeed())
			return n
		}, 5*time.Second, 100*time.Millisecond).Should(Equal(0))
	})
})

