	"github.com/sashabaranov/go-openai"
)

// poolRecorder wraps the pool constructor so a test can see every pool that
// NewPostgresDBCollection opened, and check that each one was closed.
type poolRecorder struct {
	mu    sync.Mutex
	pools []*pgxpool.Pool
}

func (r *poolRecorder) install() (restore func()) {
	orig := newPool
	newPool = func(ctx context.Context, cfg *pgxpool.Config) (*pgxpool.Pool, error) {
		p, err := orig(ctx, cfg)
		if p != nil {
			r.mu.Lock()
			r.pools = append(r.pools, p)
			r.mu.Unlock()
		}
		return p, err
	}
	return func() { newPool = orig }
}

func (r *poolRecorder) all() []*pgxpool.Pool {
	r.mu.Lock()
	defer r.mu.Unlock()
	return append([]*pgxpool.Pool(nil), r.pools...)
}

// isClosed reports whether Close was called on the pool. Acquire on a closed
// pool fails immediately with "closed pool", without network access.
func isClosed(p *pgxpool.Pool) bool {
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	c, err := p.Acquire(ctx)
	if err == nil {
		c.Release()
		return false
	}
	return err.Error() == "closed pool"
}

// newEmbedder starts an OpenAI-compatible embeddings server. When fail is
// set, every request gets HTTP 500, as from a broken embedding model.
func newEmbedder(fail bool) (*openai.Client, *atomic.Int32, func()) {
	calls := &atomic.Int32{}
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls.Add(1)
		if fail {
			http.Error(w, "simulated embedding failure", http.StatusInternalServerError)
			return
		}
		_ = json.NewEncoder(w).Encode(map[string]any{
			"object": "list",
			"model":  "fake",
			"data": []map[string]any{{
				"object": "embedding", "index": 0, "embedding": []float32{0.1, 0.2, 0.3, 0.4},
			}},
		})
	}))
	cfg := openai.DefaultConfig("sk-test")
	cfg.BaseURL = srv.URL + "/v1"
	return openai.NewClientWithConfig(cfg), calls, srv.Close
}

var _ = Describe("NewPostgresDBCollection pool lifecycle", func() {
	var (
		rec     *poolRecorder
		restore func()
	)

	BeforeEach(func() {
		rec = &poolRecorder{}
		restore = rec.install()
	})

	AfterEach(func() {
		restore()
	})

	// An address where nothing listens, so Ping fails fast without a database.
	const unreachableURL = "postgres://u:p@127.0.0.1:1/db?sslmode=disable&connect_timeout=2"

	It("leaves no open pool when the test embedding fails repeatedly", func() {
		client, calls, stop := newEmbedder(true)
		defer stop()

		for i := 0; i < 5; i++ {
			db, err := NewPostgresDBCollection("leak_test", unreachableURL, client, "fake")
			Expect(err).To(HaveOccurred())
			Expect(db).To(BeNil())
		}
		Expect(calls.Load()).To(BeNumerically(">=", 5), "the embedder must be asked on every attempt")
		for _, p := range rec.all() {
			Expect(isClosed(p)).To(BeTrue(), "a pool opened by a failed attempt was not closed")
		}
	})

	It("closes the pool every time the database ping fails", func() {
		client, _, stop := newEmbedder(false)
		defer stop()

		for i := 0; i < 5; i++ {
			db, err := NewPostgresDBCollection("leak_test", unreachableURL, client, "fake")
			Expect(err).To(MatchError(ContainSubstring("failed to ping database")))
			Expect(db).To(BeNil())
		}
		pools := rec.all()
		Expect(pools).To(HaveLen(5))
		for _, p := range pools {
			Expect(isClosed(p)).To(BeTrue(), "a pool opened by a failed attempt was not closed")
		}
	})

	Context("with a real PostgreSQL", func() {
		var databaseURL string

		BeforeEach(func() {
			databaseURL = os.Getenv("LOCALRECALL_TEST_DATABASE_URL")
			if databaseURL == "" {
				databaseURL = "postgresql://localrecall:localrecall@localhost:5432/localrecall?sslmode=disable"
			}
			ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
			defer cancel()
			p, err := pgxpool.New(ctx, databaseURL)
			if err != nil {
				Skip(fmt.Sprintf("postgres unavailable: %v", err))
			}
			defer p.Close()
			if err := p.Ping(ctx); err != nil {
				Skip(fmt.Sprintf("postgres unreachable: %v", err))
			}
		})

		It("keeps no server connection open after repeated embedding failures", func() {
			client, _, stop := newEmbedder(true)
			defer stop()

			appName := fmt.Sprintf("localrecall_leak_test_%d", time.Now().UnixNano())
			url := withApplicationName(databaseURL, appName)

			for i := 0; i < 10; i++ {
				_, err := NewPostgresDBCollection("leak_test", url, client, "fake")
				Expect(err).To(MatchError(ContainSubstring("failed to get test embedding")))
			}
			for _, p := range rec.all() {
				Expect(isClosed(p)).To(BeTrue(), "a pool opened by a failed attempt was not closed")
			}

			// The server must not see any connection left behind by the attempts.
			admin, err := pgxpool.New(context.Background(), databaseURL)
			Expect(err).NotTo(HaveOccurred())
			defer admin.Close()
			Eventually(func() int {
				var n int
				err := admin.QueryRow(context.Background(),
					"SELECT count(*) FROM pg_stat_activity WHERE application_name = $1", appName).Scan(&n)
				Expect(err).NotTo(HaveOccurred())
				return n
			}, 5*time.Second, 100*time.Millisecond).Should(Equal(0))
		})

		// An invalid lexical configuration fails schema setup after the pool
		// is open and pinged, even when BM25 is installed.
		It("keeps no server connection open after a failed schema setup", func() {
			client, _, stop := newEmbedder(false)
			defer stop()

			appName := fmt.Sprintf("localrecall_leak_test_%d", time.Now().UnixNano())
			url := withApplicationName(databaseURL, appName)

			oldConfig, hadConfig := os.LookupEnv("BM25_TEXT_CONFIG")
			Expect(os.Setenv("BM25_TEXT_CONFIG", "lr_nonexistent_text_config")).To(Succeed())
			defer func() {
				if hadConfig {
					_ = os.Setenv("BM25_TEXT_CONFIG", oldConfig)
				} else {
					_ = os.Unsetenv("BM25_TEXT_CONFIG")
				}
			}()
			name := fmt.Sprintf("leak_test_%d", time.Now().UnixNano())
			adminCleanup, err := pgxpool.New(context.Background(), databaseURL)
			Expect(err).NotTo(HaveOccurred())
			defer adminCleanup.Close()
			defer func() {
				_, _ = adminCleanup.Exec(context.Background(), "DROP TABLE IF EXISTS "+sanitizeTableName(name)+" CASCADE")
			}()
			_, err = NewPostgresDBCollection(name, url, client, "fake")
			Expect(err).To(MatchError(ContainSubstring("failed to setup database")))
			pools := rec.all()
			Expect(pools).To(HaveLen(1))
			Expect(isClosed(pools[0])).To(BeTrue())

			admin, err := pgxpool.New(context.Background(), databaseURL)
			Expect(err).NotTo(HaveOccurred())
			defer admin.Close()
			Eventually(func() int {
				var n int
				Expect(admin.QueryRow(context.Background(),
					"SELECT count(*) FROM pg_stat_activity WHERE application_name = $1", appName).Scan(&n)).To(Succeed())
				return n
			}, 5*time.Second, 100*time.Millisecond).Should(Equal(0))
		})
	})
})

// withApplicationName tags every connection opened with dsn, so the test can
// count them in pg_stat_activity.
func withApplicationName(dsn, name string) string {
	switch {
	case !strings.Contains(dsn, "://"):
		return dsn + " application_name=" + name
	case strings.Contains(dsn, "?"):
		return dsn + "&application_name=" + name
	default:
		return dsn + "?application_name=" + name
	}
}

var _ = Describe("applyPoolLimits", func() {
	noEnv := func(string) string { return "" }

	parse := func(dsn string) *pgxpool.Config {
		cfg, err := pgxpool.ParseConfig(dsn)
		Expect(err).NotTo(HaveOccurred())
		return cfg
	}

	It("caps the pool at a small default", func() {
		cfg := parse("postgres://u:p@localhost:5432/db")
		applyPoolLimits(cfg, noEnv)
		Expect(cfg.MaxConns).To(Equal(defaultPoolMaxConns))
	})

	It("keeps pool_max_conns from a URL connection string", func() {
		cfg := parse("postgres://u:p@localhost:5432/db?pool_max_conns=17")
		applyPoolLimits(cfg, func(string) string { return "3" })
		Expect(cfg.MaxConns).To(Equal(int32(17)))
	})

	It("keeps pool_max_conns from a keyword/value connection string", func() {
		cfg := parse("host=localhost user=u dbname=db pool_max_conns=9")
		applyPoolLimits(cfg, noEnv)
		Expect(cfg.MaxConns).To(Equal(int32(9)))
	})

	It("honours POSTGRES_POOL_MAX_CONNS", func() {
		cfg := parse("postgres://u:p@localhost:5432/db")
		applyPoolLimits(cfg, func(k string) string {
			if k == "POSTGRES_POOL_MAX_CONNS" {
				return "12"
			}
			return ""
		})
		Expect(cfg.MaxConns).To(Equal(int32(12)))
	})

	It("ignores an invalid POSTGRES_POOL_MAX_CONNS", func() {
		for _, v := range []string{"0", "-1", "abc"} {
			cfg := parse("postgres://u:p@localhost:5432/db")
			applyPoolLimits(cfg, func(string) string { return v })
			Expect(cfg.MaxConns).To(Equal(defaultPoolMaxConns), "value %q", v)
		}
	})
})

package postgres

import (
	"encoding/json"
	"fmt"
	"math"
	"sort"
	"strings"
	"testing"

	"github.com/mudler/localrecall/rag/internal/pgutil"
	"github.com/mudler/localrecall/rag/raw"
)

// Deterministic synthetic corpus, including many nearer excluded records.
func rankedCorpus(t *testing.T, s *Service, id string) []raw.Record {
	t.Helper()
	rs := make([]raw.Record, 600)
	for i := range rs {
		group := "other"
		if i%17 == 0 {
			group = "keep"
		}
		text := "bicycle"
		rs[i] = raw.Record{ID: fmt.Sprintf("%04d", i), Vector: []float64{math.Cos(float64(i) * 0.017), math.Sin(float64(i) * 0.017), 0.1}, Text: &text, Metadata: map[string]string{"group": group}}
	}
	for i := 0; i < len(rs); i += 100 {
		put(t, s, t.Context(), id, rs[i:i+100]...)
	}
	return rs
}
func TestRawExplain(t *testing.T) {
	s, ctx, id := recordFixture(t)
	rankedCorpus(t, s, id)
	table, _ := tableName(id)
	exec(t, s, "ANALYZE "+table)
	tx, e := s.pool.Begin(ctx)
	if e != nil {
		t.Fatal(e)
	}
	defer tx.Rollback(ctx)
	strategy, e := pgutil.IndexStrategy(ctx, tx, table, "lr_ann_"+id, "vector")
	if e != nil || (strategy != "hnsw" && strategy != "diskann") {
		t.Fatalf("ANN unavailable: %q %v", strategy, e)
	}
	// Bias toward indexes to make the exact fence assertion meaningful.
	if _, e = tx.Exec(ctx, "SET LOCAL enable_seqscan=off"); e != nil {
		t.Fatal(e)
	}
	for _, exact := range []bool{true, false} {
		args := []any{"[1,0,0]", 10}
		predicate := metadataPredicate(&raw.Filter{MetadataEq: map[string]string{"group": "keep"}}, &args)
		var plan []byte
		if e = tx.QueryRow(ctx, "EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON) "+vectorQuery(table, predicate, exact), args...).Scan(&plan); e != nil {
			t.Fatal(e)
		}
		if !json.Valid(plan) {
			t.Fatal(string(plan))
		}
		t.Logf("exact=%v dimensions=3 corpus=600 selective=1/17 plan=%s", exact, plan)
		if exact && (strings.Contains(string(plan), "lr_ann_") || !strings.Contains(string(plan), "CTE Scan")) {
			t.Fatal("exact ranking must be fenced from ANN", string(plan))
		}
		if !exact && !strings.Contains(string(plan), "lr_ann_"+id) {
			t.Fatal("fixture must demonstrate generated approximate query has an ANN access path", string(plan))
		}
	}
}
func TestRawRecallBruteForce(t *testing.T) {
	s, ctx, id := recordFixture(t)
	rs := rankedCorpus(t, s, id)
	type hit struct {
		id    string
		score float64
	}
	want := []hit{}
	for _, r := range rs {
		if r.Metadata["group"] != "keep" {
			continue
		}
		v, e := raw.NormalizeVector(r.Vector, 3)
		if e != nil {
			t.Fatal(e)
		}
		norm := 0.0
		for _, x := range v {
			norm += float64(x) * float64(x)
		}
		want = append(want, hit{r.ID, float64(v[0]) / math.Sqrt(norm)})
	}
	sort.Slice(want, func(i, j int) bool {
		if want[i].score == want[j].score {
			return want[i].id < want[j].id
		}
		return want[i].score > want[j].score
	})
	r := searchRequest("vector")
	r.Filter = &raw.Filter{MetadataEq: map[string]string{"group": "keep"}}
	exact, e := s.Search(ctx, id, r)
	if e != nil || exact.Count != 10 {
		t.Fatal(exact, e)
	}
	for i, h := range exact.Results {
		if h.ID != want[i].id || math.Abs(h.Score-want[i].score) > 1e-6 || h.VectorSimilarity == nil || *h.VectorSimilarity != h.Score {
			t.Fatalf("rank %d got %+v want %+v", i, h, want[i])
		}
	}
	r.Accuracy = nil
	approx, e := s.Search(ctx, id, r)
	if e != nil {
		t.Fatal(e)
	}
	hits := 0
	for _, h := range approx.Results {
		if h.Metadata["group"] != "keep" {
			t.Fatal("filter escaped", h)
		}
		for _, w := range want[:10] {
			if w.id == h.ID {
				hits++
			}
		}
	}
	if approx.Count > 10 || approx.Accuracy != "approximate" {
		t.Fatal(approx)
	}
	t.Logf("synthetic dimensions=3 corpus=600 eligible=%d k=10 returned=%d recall@10=%.2f underfill=%d (planner-dependent, not an ANN quality guarantee)", len(want), approx.Count, float64(hits)/10, 10-approx.Count)
}

